import os
from datetime import datetime
from typing import List, Dict, Any

# Constants
POSTS_FILE = 'posts.json'
COMMENTS_FILE = 'comments.json'


class Post:
    def __init__(self, title: str, content: str, author: str, post_id: str = None, created_at: str = None, updated_at: str = None):
        self.post_id = post_id or self._generate_id()
        self.title = title
        self.content = content
        self.author = author
        self.created_at = created_at or self._get_timestamp()
        self.updated_at = updated_at or self._get_timestamp()

    def _generate_id(self) -> str:
        return datetime.now().strftime("%Y%m%d%H%M%S%f")

    def _get_timestamp(self) -> str:
        return datetime.now().isoformat()

    def to_dict(self) -> Dict[str, Any]:
        return {
            'post_id': self.post_id,
            'title': self.title,
            'content': self.content,
            'author': self.author,
            'created_at': self.created_at,
            'updated_at': self.updated_at
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Post':
        return cls(
            title=data['title'],
            content=data['content'],
            author=data['author'],
            post_id=data['post_id'],
            created_at=data['created_at'],
            updated_at=data['updated_at']
        )


class Comment:
    def __init__(self, post_id: str, author: str, content: str, comment_id: str = None, created_at: str = None):
        self.comment_id = comment_id or self._generate_id()
        self.post_id = post_id
        self.author = author
        self.content = content
        self.created_at = created_at or self._get_timestamp()

    def _generate_id(self) -> str:
        return datetime.now().strftime("%Y%m%d%H%M%S%f")

    def _get_timestamp(self) -> str:
        return datetime.now().isoformat()

    def to_dict(self) -> Dict[str, Any]:
        return {
            'comment_id': self.comment_id,
            'post_id': self.post_id,
            'author': self.author,
            'content': self.content,
            'created_at': self.created_at
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'Comment':
        return cls(
            post_id=data['post_id'],
            author=data['author'],
            content=data['content'],
            comment_id=data['comment_id'],
            created_at=data['created_at']
        )


class PersistenceLayer:
    @staticmethod
    def load_data(file_path: str) -> List[Dict[str, Any]]:
        if not os.path.exists(file_path):
            return []

        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except (json.JSONDecodeError, IOError) as e:
            print(f"Error loading data from {file_path}: {e}")
            return []

    @staticmethod
    def save_data(file_path: str, data: List[Dict[str, Any]]) -> bool:
        try:
            with open(file_path, 'w') as file:
                json.dump(data, file, indent=2)
            return True
        except IOError as e:
            print(f"Error saving data to {file_path}: {e}")
            return False


class BlogManager:
    def __init__(self):
        self.persistence = PersistenceLayer()

    def create_post(self, title: str, content: str, author: str) -> Post:
        post = Post(title=title, content=content, author=author)
        posts = self.persistence.load_data(POSTS_FILE)
        posts.append(post.to_dict())
        self.persistence.save_data(POSTS_FILE, posts)
        return post

    def get_post(self, post_id: str) -> Post:
        posts = self.persistence.load_data(POSTS_FILE)
        for post_data in posts:
            if post_data['post_id'] == post_id:
                return Post.from_dict(post_data)
        return None

    def get_posts(self) -> List[Post]:
        posts_data = self.persistence.load_data(POSTS_FILE)
        return [Post.from_dict(post_data) for post_data in posts_data]

    def update_post(self, post_id: str, title: str = None, content: str = None, author: str = None) -> bool:
        posts = self.persistence.load_data(POSTS_FILE)
        for post_data in posts:
            if post_data['post_id'] == post_id:
                if title is not None:
                    post_data['title'] = title
                if content is not None:
                    post_data['content'] = content
                if author is not None:
                    post_data['author'] = author
                post_data['updated_at'] = datetime.now().isoformat()
                self.persistence.save_data(POSTS_FILE, posts)
                return True
        return False

    def delete_post(self, post_id: str) -> bool:
        posts = self.persistence.load_data(POSTS_FILE)
        original_length = len(posts)
        posts = [post for post in posts if post['post_id'] != post_id]
        if len(posts) < original_length:
            self.persistence.save_data(POSTS_FILE, posts)
            return True
        return False

    def create_comment(self, post_id: str, author: str, content: str) -> Comment:
        comment = Comment(post_id=post_id, author=author, content=content)
        comments = self.persistence.load_data(COMMENTS_FILE)
        comments.append(comment.to_dict())
        self.persistence.save_data(COMMENTS_FILE, comments)
        return comment

    def get_comments_for_post(self, post_id: str) -> List[Comment]:
        comments_data = self.persistence.load_data(COMMENTS_FILE)
        post_comments = [comment_data for comment_data in comments_data if comment_data['post_id'] == post_id]
        return [Comment.from_dict(comment_data) for comment_data in post_comments]

    def get_comment(self, comment_id: str) -> Comment:
        comments = self.persistence.load_data(COMMENTS_FILE)
        for comment_data in comments:
            if comment_data['comment_id'] == comment_id:
                return Comment.from_dict(comment_data)
        return None

    def update_comment(self, comment_id: str, content: str = None) -> bool:
        comments = self.persistence.load_data(COMMENTS_FILE)
        for comment_data in comments:
            if comment_data['comment_id'] == comment_id:
                if content is not None:
                    comment_data['content'] = content
                self.persistence.save_data(COMMENTS_FILE, comments)
                return True
        return False

    def delete_comment(self, comment_id: str) -> bool:
        comments = self.persistence.load_data(COMMENTS_FILE)
        original_length = len(comments)
        comments = [comment for comment in comments if comment['comment_id'] != comment_id]
        if len(comments) < original_length:
            self.persistence.save_data(COMMENTS_FILE, comments)
            return True
        return False


# Example usage
if __name__ == "__main__":
    # Initialize the blog manager
    blog = BlogManager()

    # Create a post
    post = blog.create_post("My First Blog Post", "This is the content of my first blog post.", "John Doe")
    print(f"Created post: {post.title}")

    # Get the post
    retrieved_post = blog.get_post(post.post_id)
    print(f"Retrieved post: {retrieved_post.title}")

    # Update the post
    blog.update_post(post.post_id, title="My Updated Blog Post")
    updated_post = blog.get_post(post.post_id)
    print(f"Updated post title: {updated_post.title}")

    # Create a comment
    comment = blog.create_comment(post.post_id, "Jane Smith", "Great post!")
    print(f"Created comment: {comment.content}")

    # Get comments for the post
    comments = blog.get_comments_for_post(post.post_id)
    print(f"Found {len(comments)} comments for the post")

    # List all posts
    all_posts = blog.get_posts()
    print(f"Total posts: {len(all_posts)}")

    # Delete the post
    blog.delete_post(post.post_id)
    print("Post deleted")

    # Verify deletion
    remaining_posts = blog.get_posts()
    print(f"Remaining posts: {len(remaining_posts)}")
